python3 - << 'EOF'
# Priors on Day 7:
priors = {
    "e24": 0.4793, "e36": 0.3027, "e22": 0.1639,
    "e17": 0.0183, "e06": 0.0153, "e03": 0.0119,
    "e10": 0.0034, "e30": 0.0029, "e05": 0.0012, "e32": 0.0012,
    "e00": 0.0
}

c7_1 = {"e24": "A", "e36": "B", "e22": "C", "e00": "C"}
c7_2 = {"e24": "X", "e36": "Y", "e17": "Z", "e06": "Z"}

for name, can in [("c7_1", c7_1), ("c7_2", c7_2)]:
    print(f"=== If {name} leaks ===")
    for v in sorted(set(can.values())):
        post = {}
        for e, p in priors.items():
            if e in can:
                post[e] = p * (0.95 if can[e] == v else 0.025)
        tot = sum(post.values())
        top = sorted(post.items(), key=lambda x: -x[1])
        print(f"  variant {v}: " + ", ".join(f"{e}={w/tot:.4f}" for e, w in top if w > 0))
EOF
